  van: { name: "Van", heightRange: "6'8\" and up", length: "26+ feet" }
};
function getRecommendedCarSize(customerHeight: number): CarSize {
  let recommendedCarSize: CarSize | undefined = undefined;
  for (const carSize in carSizes) {
    const heightRange = carSizes[carSize].heightRange.split(" - ") as string[];
    const startHeight = parseInt(heightRange[0], 10);
    const endHeight = parseInt(heightRange[1], 10);
    if (startHeight <= customerHeight && customerHeight <= endHeight) {
      recommendedCarSize = carSize;
      break;
    }
  }
