function smart_sort_array($set, $order) {
   $sortedArray = $set;

   // Get all ages from the sub-arrays
   $ages = array();
   foreach ($set as $subArray) {
      $ages[] = $subArray['age'];
   }

   // Sort the ages based on the order parameter
   rsort($ages, $order == 'desc');

   // Loop through the set again and update the indices of the sorted array
   $index = 0;
   foreach ($set as $subArray) {
      $sortedArray[$index] = $subArray;
      $index++;
      foreach ($ages as $key => $age) {
         if (isset($set[$key])) {
            unset($set[$key]);
            $set[] = $subArray;
            break;
         }
      }
   }

   return $sortedArray;
}

