function getMatches(obj, path) {
  let result = [];
  let currentObj = obj;

  // Split path into keys
  const paths = path.split('.');

  for (let I = 0; I < paths.length - 1; i++) {
    if (!currentObj[paths[i]]) {
      return result; // If any key is missing, stop searching
    }
    currentObj = currentObj[paths[i]];
  }

  // Get last key and check its value
  const lastKey = paths[paths.length - 1];
  for (let key in currentObj) {
    if (key === lastKey && typeof currentObj[lastKey] === 'object') {
      // Recursively search nested object
      const nestedResult = getMatches(currentObj[lastKey], path);
      result.push(...nestedResult);
    } else if (key === lastKey) {
      // Add matching entry
      result.push(currentObj[lastKey]);
    }
  }

  return result;
}
```

The `getMatches` function takes two arguments: the object to search (`obj`) and the dot-separated path to the target property (`path`). It returns an array containing all entries in `obj` whose final key matches the given path. The function recursively searches nested objects and arrays until it reaches the last key or finds a mismatch.

