	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "path/to/source.go", parser.ParseComments, parser.AllErrors)
	if err != nil {
		return nil, fmt.Errorf("error parsing file: %w", err)
	}

	// Find the type declaration for the selected struct
	for _, decl := range file.Decls {
		switch d := decl.(type) {
		case *ast.GenDecl:
			for _, spec := range d.Specs {
				switch s := spec.(type) {
