Here's a C# program that uses natural language generation to summarize the main points of the given article:

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ClimateChangeSummary
{
    class Program
    {
        static void Main(string[] args)
        {
            string text = File.ReadAllText("climatechangearticle.txt");
            List<string> sentences = text.Split(new[] { '.' }, StringSplitOptions.RemoveEmptyEntries).ToList();

            // Define weights for helpfulness and verbosity
            int helpfulnessWeight = 97;
            int verbosityWeight = 26;

            // Calculate scores for each sentence based on its helpfulness and verbosity
            Dictionary<string, int> scores = new Dictionary<string, int>();
            foreach (string sentence in sentences)
            {
                int helpfulnessScore = 0;
                int verbosityScore = sentence.Length - sentence.Replace(" ", "").Length;
                int totalScore = helpfulnessScore * helpfulnessWeight + verbosityScore * verbosityWeight;
                scores.Add(sentence, totalScore);
            }

            // Sort sentences by their scores
            List<KeyValuePair<string, int>> sortedSentences = scores.OrderByDescending(x => x.Value).ToList();

            // Print summary based on top-scoring sentences
            Console.Write("Climate Change Summary:\n");
            foreach (var pair in sortedSentences.Take(5))
            {
                Console.WriteLine(pair.Key);
            }
            Console.ReadLine();
        }
    }
}
```

This program reads the article as a string, splits it into sentences, and calculates scores for each sentence based on its helpfulness and verbosity using the weights defined at the beginning. It then sorts the sentences by score and prints the top five sentences as a summary. You can adjust the weights to suit your preferences or modify the summary logic as needed. This is just an example of how natural language generation can be implemented in C#.

