$logEnabled = $true
```

2. Define a function `checkacl` that takes a path as input and returns `$true` if the acls of the given folder or subfolders contain sids found only in sidhistory, otherwise `$false`. This function will be called recursively by the main script.

```powershell
function CheckACL($path) {
    $acls = get-acla $path | select -expandproperty access
    foreach ($acl in $acls) {
        $identity = $acl.IdentityReference
        $sidhistory = Get-ADUser -filter {SamAccountName -eq $identity.value} | Select-Object -ExpandProperty SidHistory | Select-Object -ExpandProperty SubAuthority
        if (-not [string]::join(" ", $sidhistory)) {
            return $false
        }
        $isInSidHistory = $false
        foreach ($subAuth in $sidhistory) {
            $allSubAuths = (Get-ADGroupMember -recursive -filter {SamAccountName -eq $identity.value}) | Select-Object -ExpandProperty SidHistory | Select-Object -ExpandProperty SubAuthority
            foreach ($subAuthAll in $allSubAuths) {
                if (-not ([math]::abs(int($subAuth)) -eq [math]::abs(int($subAuthAll)))) { continue }
                $isInSidHistory = $true
                break
            }
            if ($isInSidHistory) { break }
        }
        if (!$isInSidHistory) { return $false }
    }
    return $true
}
```
